    accountsDesc: 'DeHub-এ প্রবেশের বেশ কয়েকটি উপায় রয়েছে এবং তাদের কোনওটিই আপনাকে ইতিমধ্যে একটি ওয়ালেটের মালিক হওয়ার প্রয়োজন নেই । গুগল, অ্যাপল বা টেলিগ্রাম দিয়ে সাইন ইন করুন, আপনার ইমেল ঠিকানায় বা এসএমএসের মাধ্যমে পাঠানো একটি কোড দিয়ে, আপনার ফোন বা কম্পিউটারে একটি পাসকি দিয়ে, অথবা আপনি ইতিমধ্যে ব্যবহার করছেন এমন একটি ওয়ালেট সংযুক্ত করে । ওয়ালেট রুট ব্যতীত সমস্ত কিছু ব্যাকগ্রাউন্ডে আপনার জন্য একটি নন-কাস্টোডিয়াল ওয়ালেট তৈরি করে: আপনি কীগুলি ধরে রাখেন, আমরা কখনই হেফাজত নিই না এবং গ্যাস স্পনসর করা হয় যাতে আপনি কোনও নেটিভ টোকেন না কিনে পোস্ট, টিপ এবং সংগ্রহ করতে পারেন । আপনাকে শুধুমাত্র সেই ওয়ালেটটি প্রথমবার ব্যবহার করার সময় সুরক্ষিত রাখতে বলা হয়, সাইন আপ করার সময় নয় ।',
    accountsDesc2: 'একজন ব্যক্তি একই ব্রাউজার থেকে একাধিক পরিচিতি চালাতে পারেন । প্রোফাইলগুলি সেটিংস → প্রোফাইলে পরিচালিত হয়: একটি অ্যাকাউন্ট যোগ করুন, তাদের মধ্যে স্যুইচ করুন এবং DeHub এক ধাপে পুরো সেশন — ওয়ালেট, ফিড, মেসেজ এবং বিজ্ঞপ্তি — অদলবদল করে । একটি প্রোফাইল যোগ করা কখনই আপনাকে আপনি যেটিতে আছেন তার থেকে সাইন আউট করে না এবং একটি স্যুইচ যা সম্পূর্ণ করা যায় না তা আপনি যেখানে ছিলেন সেখানে ফিরে যায় । আপনি আপনার স্ট্যাকিং ব্যাজ দিয়ে তালিকা স্কেলে কতগুলি প্রোফাইল পার্ক করতে পারেন ।',
