    intro3: '2023-এ কন্টেন্ট টোকেনাইজ গরার প্রথম প্রোটোকল হিসাবে, আমরা একটা টেকসই socialfi সমাধান বানাইছি। ফিচারে আছে এনক্রিপ্টেড প্রাইভেট কমিউনিকেশন, অন-চেইন PPV, ট্রেডেবল সাবস্ক্রিপশন, পেইড DM, আনলকেবল কন্টেন্ট আর আরো অনেক।',
    intro4: 'যেহেতু ডেটা হইলো নতুন তেল, তোমার কোর কমিউনিটি এইহানে বানানো বুদ্ধিমানের কাজ অইবো আর বিদ্যমান সোশ্যাল মিডিয়া থাইকা ইউজার আনো।',
