    accountsB1Desc: 'গুগল, অ্যাপল অথবা টেলিগ্রাম, একটা ট্যাপে ওয়ালেট বানিয়ে ফেলো, আর প্রথম পোস্ট থেকেই গ্যাস স্পন্সর করা থাকবে।',
    accountsB3Desc: 'কোনো ওয়ালেট কানেক্ট করো—মেটামাস্ক, রেইনবো, ট্রাস্ট, ফ্যান্টম অথবা ওয়ালেটকানেক্টের সাথে কথা বলতে পারা যেকোনো ওয়ালেট—এবং একবার সাইন করো যাতে ঠিকানা প্রমাণিত হয়। যদি ফ্যান্টম সাইন-ইন মেনে না নেয় কারণ এর ইথেরিয়াম ঠিকানায় কোনো হিস্টরি নেই, তাহলে তোমার সোলানা ওয়ালেটের ঠিকানা দিয়ে প্রমাণ করো। ওয়ালেট ইউজারদের নিজস্ব গ্যাসের খরচ বহন করতে হয়।',
    accountsB6: 'পাসওয়ার্ড:',
    accountsB6Desc: 'ফিঙ্গারপ্রিন্ট দিয়ে \'কন্টিনিউ\' বাছাই করো আর পাসকি হচ্ছে একাউন্টের নাম—ইমেইল নেই, ফোন নম্বর নেই, পাসওয়ার্ড নেই। একই পাসকি ওয়েবসাইটে আর অ্যান্ড্রয়েড অ্যাপে কাজ করে।',
    accountsB7Desc: 'ওই সাইন-ইন ফর্মে তোমার ইতিমধ্যে থাকা ওয়ালেটের কীগুলো ইম্পোর্ট করার ও আগের ডিহাব অ্যাকাউন্ট মাইগ্রেট করার জন্য আলাদা আলাদা অপশন আছে। তাই নতুন রেজিস্ট্রেশন করবেন তো না, দুটোই একসাথে বাছাই করতে হবেনা।',
    accountsB8: 'ছাড়া',
    accountsB8Desc: 'আপনার অ্যাকাউন্ট নিজেই সেটিংস থেকে মুছে ফেলতে পারেন। আপনার প্রোফাইল, আপলোড এবং স্টোরেড মিডিয়া, যার মধ্যে ব্যাকআপ কপি রয়েছে, মুছে ফেলা হয়ে যায়, এবং একটি সাইন ইন উইথ এপল লিংক বাতিল হয়ে যায়। কোনো কিছু ইতিমধ্যেই একটি পাবলিক ব্লকচেইনে লেখা থাকলে সেটা সেখানেই থাকে।',
    uploadGallery: 'একটা পোস্টে একের বদলে বেশ কয়েকটা ছবি রাখা যায়: বেজ বাদেজ ছাড়া চারটা, প্রতিটি বাদেজ টিয়ার বেড়ে মেগালোডন এ পঁচিশটা, আর প্রতিটি ছবির সাইজ সর্বোচ্চ ৪২.০৬৯ এমবি। পোস্ট করার আগে চাইলে ছবিগুলোকে আপনার ইচ্ছামতো সাজিয়ে ফেলুন, কম্পোজারে ছবিতে আঁকতে বা লিখতে পারবেন, আর কোনো ছবি ফুলস্ক্রিনে খুললে আপনি অরিজিনাল ফাইল ফুল রেজোলিউশনে দেখতে পাবেন, পিনচ করে জুম করতে পারবেন।',
    labelComposerTools: 'কম্পোজার টুলস:',
    profileB2Desc: 'কোনো অ্যাপের মধ্যে ব্যাডজে ক্লিক করলে তা ব্যাডজ শোকোসে খুলবে, যেখানে এর টিয়ার এবং কী কী আনলক করবে সেটা দেখাবে।',
    profileB3: 'টোটাল রিচ:',
    profileB4: 'প্লেলিস্টস:',
    profileB5Desc: 'ওই চ্যানেলের পোস্টগুলো ক্যাটাগরি, ডেট, টাইপ ও অ্যাক্সেস অনুযায়ী সার্চ, সর্ট ও ফিল্টার করতে পারবেন। এছাড়াও লাইভ হবার আগে স্কেচুল্ড পোস্টগুলো দেখতে পারবেন।',
    profileB6Desc: 'একটা ভেরিফাইড ইএনএস নাম আপনার প্রোফাইল ঠিকানা হিসেবে কাজ করে, ডিহাব ইউজারনেমের পাশাপাশি।',
    tipDesc3: 'টিপস পোস্ট, কমেন্ট, ডিরেক্ট মেসেজ এবং লাইভ স্ট্রিমে কাজ করে। যদি আপনার ডিহাব টোকেন কম থাকে, তাহলে টিপ শিট আপনার অন্যান্য ব্যালেন্সগুলো দেখাবে — ইউএসডিসি, ইথি বা বেস, বিএনবি চেইন, রবিনহুড চেইন বা আর্কের টোকেন — এবং টিপ যাওয়ার আগে তা আপনার জন্য কনভার্ট করে দেবে। একবার আপনি কোনো পোস্ট টিপ দিলে, তার টিপ বাটনে একটি চমকপ্রদ ডায়মন্ড দেখাবে যাতে আপনি দেখতে পারবেন যে আপনি ইতিমধ্যে টিপ দিয়েছেন।',
    backendLabel: 'ইংগেস্ট করো',
    frontendDesc: 'দর্শকরা ওয়েবরিটিসিএল এ নিকট বাস্তব সময়ে দেখতে পারে, ফিড এবং পোস্ট পেজে, এবং একটি স্ট্রিম যা শেষ হয় তার পুনরাবৃত্তি হয় যাতে পুনরায় লোড না হয়',
