    militaryGradeDesc: 'আপনার ডিভাইসে মেসেজ টেক্সট ও ক্যাপশন আপনার ও অন্য ব্যক্তির কী দিয়ে এনক্রিপ্টেড থাকে। যদি অন্য ব্যক্তি কখনো এনক্রিপ্টেড মেসেজ আনলক করেননি, তাহলে মেসেজ আনএনক্রিপ্টেড পাঠানো হয়।',
