    articlesDesc: 'লং-ফর্ম লিখন তার নিজস্ব মোড আছে। কম্পোজারটিকে পোস্ট থেকে আর্টিকেলে স্যুইচ করলে তুমি পাবো একটা টাইটেল, একটা বডি (ম্যাক্সিমাম ২০,০০০ চরিত্র), ফরম্যাটিং টুলবার, একটা কভার ইমেজ এবং দেখার পূর্বরূপ কেমন হবে সেটা। একটা আর্টিকেলও যেকোনো পোস্টের মতো পাবলিশ হয়, তাই সেটা টিপ করা, কোট করা, গেট করা এবং শেয়ার করা যায়। আর যখন লিংক অন্য কোথাও পোস্ট করা হয়, তখন সেটার নিজস্ব শেয়ার কার্ড থাকে।',
    multipostDesc: 'প্রকাশ করুন DeHub এ এবং আপনার অন্যান্য সোশ্যাল অ্যাকাউন্টে একই ধাপে। সেটিংস → মাল্টি-পোস্ট এ একবার অ্যাকাউন্ট সংযুক্ত করুন, তারপর কম্পোজারে ক্রস-পোস্ট আইকন থেকে প্রতিটি পোস্টের যেখানে যাবে তা বেছে নিন। DeHub পোস্টের ঘর; কপিগুলো আপনার ইতিমধ্যে থাকা অন্যান্য সম্প্রদায়ে নিয়ে যায়।',
