    multipostB2: 'পোস্ট ক্রেডিট:',
    communitiesB2Desc: 'একেকটা কমিউনিটি আছে নিজস্ব ফিড আর চ্যাট, যেখানে সদস্যরা পোস্ট করে, আলোচনা করে, পোল চালায়, একে অপরের @মেন্টিয়ন করে আর টিপ দেয়। এই সব মডারেট করে কমিউনিটির মালিক।',
    walletHubB5: 'সোলানা:',
    walletHubB5Desc: 'সেটিংস-এ একখান সোলানা ওয়ালেট কানেক্ট করুন, আপনার সবকিছুর লগে এর হোল্ডিং দেখতে আর জুপিতার দিয়া ট্রেড করতে।',
    tocExchange: 'এক্সচেঞ্জ',
    exchangeTitle: 'এক্সচেঞ্জ',
