    storesB1Desc: 'কোনো ক্রিয়েটর বা ব্যবসা নিজস্ব পেজ, ব্র্যান্ডিং আর প্রোডাক্ট লিস্টিংসহ একটা স্টোরফ্রন্ট খুলতে পারে।',
