    aiSuiteB4Desc: 'একটা নেটিভ জেনারেশন স্টুডিও ইমেজ, ভিডিও, ভয়েস, মিউজিক আর ৩ডি মডেলের জন্য, ক্যানভা-স্টাইল এডিটরসহ, শেয়ার্ড রেন্ডার কিউ যা তোমার ব্রাউজিং করার সময়ও কাজ করে, আর ফ্রি স্টক এসেট লাইব্রেরি থেকে ডাউনলোড করার সুবিধা।',
    aiSuiteB5Desc: '@assistant কে কোনো পোস্টে, কমেন্ট থ্রেডে অথবা লাইভ চ্যাটে মেনশন করলে সে রিয়েল প্ল্যাটফর্ম টুল ব্যবহার করে সেখানে উত্তর দিবে, না হলে কীওয়ার্ড ম্যাচিং করবে না। এছাড়াও সে একজন মানবের কাছে সমর্থন টিকিটও ফাইল করতে পারে।',
