    appsDesc: 'DeHub চোখে চোখে দেয়। dehub.io তে থাকা ওয়েব অ্যাপটি ব্রাউজারে পুরো প্রোডাক্ট আর ডেস্কটপ ও ফোনে হোম স্ক্রিনে ইনস্টল হয়ে যাবে নেটিভ অ্যাপের মতো। অ্যান্ড্রয়েড অ্যাপটি গুগল প্লেতে আছে, আর সর্বশেষ বিল্ডটা সবাইকে জন্যে ডাইরেক্ট এপিকে থেকে পাওয়া যাবে dehub.io/apk থেকে যারা স্টোর কাটাতে চাইবে। ফিড, স্টেজ, পোস্টিং, মেসেজিং, ওয়ালেট আর নোটিফিকেশন সবই একই রকম কাজ করে দুটোতেই, আর আপনার অ্যাকাউন্ট, ব্যাডজ আর ব্যালেন্স দুটোতেই একসাথে থাকে।',
    appsB2Desc: 'ও গুগল প্লে-তে, অথবা ডাইরেক্ট এপিকে ডাউনলোড করুন দেহুব.আইও/এপিকে থেকে অ্যান্ড্রয়েড ৮ ও উপরে ভের্সন-এর জন্য।',
    appsB3Desc: 'একই সাইন-ইন, ওয়ালেট, ব্যাডজ এবং ব্যালেন্স সব জায়গাতেই, কোন আলাদা মাইগ্রেশন স্টেপ ছাড়াই।',
