    nft3: 'ক্রিয়েটরর পেমেন্ট সরাসরি তার ওয়ালেটত জমা অইবো',
    forCreatorsSubs5: 'সরাসরি পেমেন্ট, তবে আপনার ব্যাজ অনুযায়ী কিছু ফি কাটা যাইবো',
