    mon4: 'চ্যাটর ভিতর টিপ দিন, আপনার কাছে যে টোকেন আছে তা দি পেমেন্ট করুন',
    militaryGrade: 'এনক্রিপ্টেড টেক্সট',
    privateByDesignDesc: 'DeHub শুধু এনক্রিপ্টেড মেসেজর সাইফারটেক্সট জমা রাখে। আপনার কি (key) আপনার ডিভাইসর ওয়ালেট সিগনেচার দি তৈরি অয় আর তা কোনোদিনও আমাদের কাছে পাঠানো অয় না।',
    secureMediaSharing: 'যা এনক্রিপ্টেড না',
    secureMediaDesc: 'ফটো, ভিডিও আর ফাইল এখনো এন্ড-টু-এন্ড এনক্রিপ্টেড না, আর DeHub দেখতে পারিবো আপনি কার লগে মেসেজ করতেছেন আর কখন, কারণ মেসেজ ডেলিভারি করার লাই সব মেসেঞ্জাররই এইটা জানা লাগে।',
    priorityMessages: 'পেইড মেসেজ',
    pri2: 'পাঠানোর আগে ফি দেখা যাইবো',
