    commUser1: 'ডিফল্টভাবে এন্ড-টু-এন্ড এনক্রিপ্টেড টেক্সট',
    boostPower: '১) বুস্ট',
    boostPowerDesc: 'গত এক সপ্তাহর মইধ্যে করা যেকোনো পোস্ট হোম ফিডর একদম উপরে আনুন। ক্র্যাব (Crab) ব্যাজ পাইলে এইটা খুলবো। এখন চালু আছে।',
    secondWindPower: '২) সেকেন্ড উইন্ড',
    secondWindPowerDesc: 'এক সপ্তাহর বেশি পুরান পোস্ট আবার ফিডর উপরে আনুন। ঘোস্ট লবস্টার (Ghost Lobster) ব্যাজ পাইলে এইটা খুলবো। এখন চালু আছে।',
    trendJackerDesc2: 'আপনার যেকোনো একটা ক্যাটাগরি ট্রেন্ডিং লিস্টর উপরে আনুন। জায়ান্ট টরটয়েজ (Giant Tortoise) ব্যাজ পাইলে এইটা খুলবো। এখন চালু আছে।',
    superPowersMore2: 'বারোটা পাওয়ারই এখন চালু আছে আর অ্যাপত লিস্ট করা আছে। কমেন্ট অ্যাঙ্কর (Comment Anchor) দি অন্য কারো থ্রেডর উপরে আপনার কমেন্ট ধরি রাখা যাইবো। সিগন্যাল ফ্লেয়ার (Signal Flare) দি আপনাকে ফলো করা সব অ্যাকাউন্টত একটা নোটিফিকেশন পাঠানো যাইবো। ফ্ল্যাক জ্যাকেট (Flak Jacket) দি পোস্টরে ডাউনভোট দি হারাই যাওয়া থনে বাঁচানো যাইবো। টিম আপ (Team up) দি আটটা পর্যন্ত অ্যাকাউন্ট মিলাই তাদের ওয়ালেট পাওয়ার যোগ করা যাইবো, যাতে সব মেম্বার তাদের টোটাল ব্যালেন্স অনুযায়ী ব্যাজ পাইবো। ফ্রন্ট রো (Front Row) দি আপনার হোস্ট করা স্টেজরে স্টেজ রেইলর উপরে আনা যাইবো। ডিপ কারেন্ট (Deep Current) দি আপনার একটা বুস্ট অন্য কারো পোস্টত দেওয়া যাইবো।',
    superPowersMoreV2: 'বারোটা পাওয়ারই লাইভ আছে আর অ্যাপের লিস্টে দেওয়া আছে। Comment Anchor আপনার কমেন্টরে অন্য কারো থ্রেডের একদম উপরে ধরি রাখে। Signal Flare আপনার ফলোয়ার সব একাউন্টরে একটা নোটিফিকেশন পাঠায়। Flak Jacket একটা পোস্টরে ডাউনভোট খাইয়া হারাইয়া যাওয়া থন বাঁচায়। Team up দি আটজন পর্যন্ত একাউন্ট মিলে তাদের ওয়ালেট পাওয়ার এক করতে পারে, যাতে সব মেম্বার তাদের জমানো ব্যালেন্স অনুযায়ী ব্যাজ পাইবো। Front Row আপনার হোস্ট করা স্টেজরে স্টেজ রেইলের একদম উপরে নিয়া যায়। Deep Current আপনার একটা বুস্ট অন্য কারো পোস্টে দিতে সাহায্য করে।',
    superPowersLink: 'আপনার এলাউন্স আর পুরা লেডারটা দেখেন',
    spPowersTitle: 'বারোটা পাওয়ার',
    spPowersLead: 'ব্যাজ লেডারের প্রতিটা ধাপ একটা কইরা পাওয়ার আনলক করে, আর আপনি যা যা আনলক করছেন তা সবসময় আনলকই থাকবো। এইগুলা সব একই পাক্ষিক এলাউন্স থন খরচ হয়, তাই কোনটা খরচ করবেন সেইটা আপনার ইচ্ছা।',
