    spDescSecondWind: 'এক সপ্তাহের বেশি পুরান কোনো পোস্টরে আবার ফিডের উপরে নিয়া আসেন।',
    spDescCommentAnchor: 'অন্য কারো কমেন্ট থ্রেডের উপরে ধরি রাখেন। লেখক তার নিজের পোস্টে যে ফ্রি পিন পায় সেইটা না—এইটা আপনার, অন্য কারো থ্রেডে, আর এইটা একটা নির্দিষ্ট সময় পর শেষ হইয়া যায়।',
    spDescTrendJacker: 'আপনার একটা ক্যাটাগরি ট্রেন্ডিং লিস্টে নিয়া আসেন, যেখানে পুরা প্ল্যাটফর্মের মানুষ নজর রাখে।',
    spDescHarpoon: 'আপনার পছন্দ করা ব্যাজ টায়ারের সব হোল্ডারের কাছে একটা পোস্টের নোটিফিকেশন পাঠান। এইটাও সিগন্যাল এলাউন্স থন খরচ হয়।',
    spDescTeamUp: 'অন্য সাতটা একাউন্টের সাথে ওয়ালেট পাওয়ার এক করেন। টিমের সবাই সেই ব্যাজটা পাইবো যেটা তাদের জমানো ব্যালেন্স অনুযায়ী আনলক হয়, আর এইটার জন্য কোনো খরচ নাই। টিম প্রাইভেটও হইতে পারে, যাতে মানুষ জয়েন করার জন্য রিকোয়েস্ট পাঠাইতে পারে আর ওনার তা এপ্রুভ করতে পারে।',
    spDescDeepCurrent: 'আপনার একটা বুস্ট অন্য কারো পোস্টে দেন। একদম উপরের ধাপটা হইলো সেইটা যেটা আপনার রিচ অন্য মানুষের জন্য খরচ করে।',
    spLadderTitle: 'প্রতিটা ব্যাজ যা দেয়',
