    converterB1: 'একুশটা সোর্স:',
    converterB2Desc: 'একটা চ্যানেলের অ্যাড্রেস পেস্ট করলেই পুরা চ্যানেল একসাথে চলে আসবে, থাম্বনেইল, ডিউরেশন আর ভিউ কাউন্ট দেখা যাবে, যাতে আপনি বেছে নিতে পারেন কী কী আসবে আর কাজ শুরুর আগেই দাম দেখতে পারেন।',
    converterB3Desc: 'একটা পডকাস্ট আরএসএস (RSS) ফিড পেস্ট করে একসাথে বিশটা এপিসোড পর্যন্ত ইমপোর্ট করা যায়।',
    tocMiniApps: 'মিনি অ্যাপস',
    miniAppsTitle: 'মিনি অ্যাপস',
    miniAppsDesc: 'মেনুতে আর dehub.io/apps-এ থাকা অ্যাপস হইলো মিনি অ্যাপের একটা স্টোর, যা যে কেউ ডিহাবের (DeHub) জন্য বানাইতে পারে। একটা মিনি অ্যাপ ডিহাবের ভেতরেই খোলে, যেখানে শুধু ডিহাবের হেডার থাকে, আপনি আগে থেকেই সাইন ইন করা থাকেন, আর প্রত্যেকটা অ্যাপ তার আসল ওয়েব অ্যাড্রেস দেখায়।',
    miniAppsB1: 'ডিহাব (DeHub) দিয়ে সাইন ইন করুন:',
    miniAppsB1Desc: 'কোনো অ্যাপ যখন আপনারে সাইন ইন করতে কয়, হেইডা আপনার ওয়ালেট অ্যাড্রেস আর একটা টোকেন পায় যেটা শুধু হেই অ্যাপের লাইগাই কাম করে। হেইডা কোনোদিনও আপনার ওয়ালেট, আপনার টাকা-পয়সা বা আপনার DeHub অ্যাকাউন্টের এক্সেস পায় না।',
