    arcadeTitle: 'আর্কেড',
    arcadeDesc: 'আর্কেড হইলো গেমের একটা তাক যেটা DeHub-এর ভিতরে ব্রাউজার ট্যাবে চলে। কিছু ইন্সটল করা লাগে না, কিছু কিনা লাগে না, আলাদা কোনো অ্যাকাউন্টও লাগে না: একটা খুলুন আর খেলুন। আজ ছয়টা গেম রিলিজ হইছে — King\'s Gambit, একটা সিনেমাটিক ৩ডি দাবা খেলা যেটার অনলাইন ইলো লেডার আছে; Claude of Duty, একটা শুটার গেম যেটা লেভেল লোড হওয়ার সময় আপনার মেশিনে সব মেশ, টেক্সচার আর সাউন্ড জেনারেট করে; Jungle Trail, একটা ফার্স্ট-পারসন হাঁটাচলার গেম যেটা প্রসিডিউরালি জেনারেট করা রেইনফরেস্টের ভিতর দিয়া যায়; Street Slayer, DeHub-এর লাইগা বানানো একটা সাইড-স্ক্রলিং বিট \'এম আপ গেম; Chartopia, একটা ট্রেডিং ফ্লোর যেটার ভিতর দিয়া আপনি হাঁটতে পারবেন, ডেস্ক মনিটরে লাইভ মার্কেট ফিড আছে আর WebXR দিয়া ভিআর মোডও আছে; আর God\'s Eye, একটা লাইভ ৩ডি গ্লোব যেখানে আপনি DeHub কমিউনিটির মাঝে নিজের একটা আনুমানিক ভার্সন বসাইতে পারবেন। ডেভেলপাররা তাদের নিজেদের গেম রিভিউয়ের লাইগা জমা দিতে পারবে।',
