    malExp1: "வழிகாட்டி நாய்கள்: பல துறைகளில் 5-10 பேர் கொண்ட குழுவுடன் நிதி திரட்டும் மேலாளராக>$1m திரட்டினார்",
    malExp2: "Randstad: $8bn டாலர் சந்தை மதிப்பு மற்றும் உலகின் மிகப்பெரிய ஏஜென்சியின் மூத்த ஆலோசகர்",
    malExp3: "Blue Arrow: UK இன் மிகப்பெரிய ஏஜென்சியில் (600க்கும் மேற்பட்ட ஊழியர்கள் & 70 அலுவலகங்கள் நாடு முழுவதும்) மிகப்பெரிய பில்லர் & விருது பெற்ற ஆலோசகர். வாரத்திற்கு $10,000க்கு மேல் தனிப்பட்ட நிகர லாபத்தை உற்பத்தி செய்தல் & எந்த ஒரு நேரத்திலும் 100 முழுநேர அல்லது பகுதிநேர ஊழியர்களுடன் ஆயிரக்கணக்கானோரை பணியமர்த்துதல்",
    malExp4: "ITS கட்டுமான: முன்னணி UK கட்டுமான ஏஜென்சியில் சசெக்ஸ் பிராந்திய மேலாளர். தனது சொந்த அலுவலகத்தை புதிதாக கட்டி 8 மாதங்களுக்கும் குறைவான காலத்தில் 0ல் இருந்து வாரத்திற்கு $5k ஆக மாற்றினார், UK இன் மிகவும் மதிப்புமிக்க கட்டுநரான Berkeley Homes உடன் PSL இல் கையெழுத்திட்டார், $100bn Horsham திட்டமான Highwood இல் பிரத்தியேக சப்ளையராக வெற்றி பெற்றார்.",
    mikeName: "Mike Hales",
    mikeRole: "இணை நிறுவனர்",
