    subtitle: 'নতুন অ্যাকাউন্ট থেকে প্রথম পোস্ট, টিপ এবং ব্যাজ পেতে মাত্র কয়েক মিনিট সময় লাগে।',
    prerequisites: 'আপনার যা প্রয়োজন',
    prereq1: 'একটি ওয়েব ব্রাউজার, অথবা গুগল প্লে থেকে অ্যান্ড্রয়েড অ্যাপ',
    prereq3: 'আর কিছু না: কোনো সিড ফ্রেজ লিখে রাখা লাগবে না, কোনো গ্যাস ফি কেনা লাগবে না',
    step1Title: 'আপনার অ্যাকাউন্ট তৈরি করুন',
    step1Desc: 'dehub.io ওপেন করে সাইন ইন (Sign in) ট্যাপ করুন। গুগল, অ্যাপল, টেলিগ্রাম, ইমেইল, এসএমএস, পাসকি বা ওয়ালেট বেছে নিন। ব্যাকগ্রাউন্ডে আপনার জন্য একটি নন-কাস্টোডিয়াল ওয়ালেট তৈরি হয়ে যাবে—চাবি আপনার কাছেই থাকবে—এবং গ্যাস ফি স্পনসর করা থাকে, তাই শুরু করার আগে কোনো টাকা জমানোর দরকার নেই।',
    step2Title: 'আপনার প্রোফাইল সেটআপ করুন',
    step2Desc: 'সেটিংস → প্রোফাইলে গিয়ে ডিসপ্লে নেম, ইউজারনেম, অবতার, কভার ইমেজ এবং বায়ো যোগ করুন। আপনার অন্যান্য সোশ্যাল মিডিয়া লিঙ্ক করুন যাতে আপনার প্রোফাইলে আপনার মোট রিচ দেখা যায়। সেটিংস → অ্যাপিয়ারেন্সে গিয়ে একটি থিম বেছে নিন এবং যদি ঘুরে দেখতে চান তবে ঐচ্ছিক গাইডেড ওয়াকথ্রু (walkthrough) নিতে পারেন।',
    step3Title: 'আপনার প্রথম পোস্ট করুন',
    step3Desc: 'ক্রিয়েট (Create) ট্যাপ করুন। পোস্ট লিখুন, ছবি, ভিডিও বা অডিও যোগ করুন, বড় লেখার জন্য আর্টিকেলে সুইচ করুন, অথবা লাইভে যান। ব্যাজ ছাড়া প্রতিদিন দশটি টেক্সট পোস্ট এবং এক গিগাবাইট মিডিয়া পর্যন্ত পোস্ট করা ফ্রী। অন-চেইনে পোস্ট মিন্ট করা ঐচ্ছিক এবং পরে করা যাবে।',
    step4Title: 'আপনার অডিয়েন্স থেকে আয় করুন',
    step4Desc: 'প্রতিটি পোস্টে ডিহাব টোকেন দিয়ে টিপ দেওয়া যায়। সেখান থেকে আপনি সাবস্ক্রিপশন বিক্রি করতে পারেন, পে-পার-ভিউ পোস্ট পাবলিশ করতে পারেন, সরাসরি মেসেজের জন্য মিনিমাম টিপ সেট করতে পারেন, দোকান খুলতে পারেন, বাউন্টি পোস্ট করতে পারেন এবং আপনার অ্যাফিলিয়েট লিঙ্ক শেয়ার করে আপনার আনা মানুষদের থেকে আয় করতে পারেন।',
    step5Title: 'ব্যাজের জন্য টোকেন হোল্ড করুন',
    step5Desc: 'ডিহাব টোকেন হোল্ড বা স্ট্যাক করলে ক্র্যাব (Crab) থেকে মেগালোডন (Megalodon) পর্যন্ত ব্যাজ পাওয়া যায়। ব্যাজ আপনার ফি কমায়, পোস্ট করার লিমিট বাড়ায়, সুপারপাওয়ার আনলক করে এবং আপনার ভিউ, রিঅ্যাকশন ও ভোটের ওজন বাড়ায়।',
    step6Title: 'আপনার ওয়ালেট ব্যবহার করুন',
